	• window.open('https://duckduckgo.com' + q, '_blank');

    const xhtmlNS = "https:" + "//www.w3.org/1999/xhtml";
    const root = document.getElementById("root");
    root.setAttribute("xmlns", svgNS);

    const fo = document.createElementNS(svgNS, "foreignObject");
    fo.setAttribute("width", "100%");
    fo.setAttribute("height", "100%");

    const body = document.createElementNS(xhtmlNS, "body");
    body.setAttribute("style", "margin:0; font-family:sans-serif; background:#121212; color:white; display:flex; flex-direction:column; align-items:center; justify-content:center; height:100vh;");
    body.innerHTML = `

Custom Search


        Search

    `;

    fo.appendChild(body);
    root.appendChild(fo);

    document.getElementById("searchForm").addEventListener("submit", function(e) {
      e.preventDefault();
      const q = encodeURIComponent(document.getElementById("query").value);
      window.open("https:" + "//://duckduckgo.com" + q, "_blank");
    });
